<dialog x-ref="editor" aria-labelledby="dns-editor-title" :class="editorInline ? 'static m-0 w-full max-w-none border-0 border-t border-blue-100 bg-blue-50/30 p-0 text-slate-900' : 'm-auto max-h-[90dvh] w-[calc(100%-2rem)] max-w-lg overflow-y-auto rounded-xl border border-slate-200 bg-white p-0 text-slate-900 shadow-xl backdrop:bg-slate-900/40'" @cancel.prevent="closeEditor()" @keydown.escape.stop.prevent="closeEditor()" @click="if ($event.target === $refs.editor && !editorInline) closeEditor()">
    <form method="POST" action="{{ route($prefix.'records', $zone, false) }}" @submit.prevent="save($event)" class="p-5 sm:p-6">
        @csrf<input type="hidden" name="content" x-ref="content"><input type="hidden" name="editor_mode" :value="editing ? 'edit' : 'create'">
        <div class="flex items-center justify-between gap-3"><h2 id="dns-editor-title" class="text-lg font-black" x-text="type === 'NS' ? 'واگذاری زیردامنه به نیم‌سرور دیگر' : (editing ? 'ویرایش رکورد ' + type : 'افزودن رکورد DNS')"></h2><button type="button" @click="closeEditor()" class="rounded-lg px-3 py-2 text-xl text-slate-500" aria-label="بستن">×</button></div>
        <p x-show="editing" class="mt-2 text-xs leading-6 text-slate-500">این ردیف شامل همه مقدارهای این نام و نوع است؛ تغییرات برای کل ردیف ذخیره می‌شوند.</p>
        <div role="alert" x-show="error" x-text="error" class="mt-4 rounded-xl bg-red-50 p-3 text-sm leading-7 text-red-800"></div>
        <div class="mt-5 grid grid-cols-1 gap-4 sm:grid-cols-[140px_1fr]">
            <label class="text-xs font-bold">نوع رکورد<select name="type" x-model="type" @change="changeType()" :disabled="editing" class="mt-2 w-full rounded-xl border border-slate-300 px-3 py-3 font-mono text-sm" dir="ltr">@foreach($types as $type)<option>{{ $type }}</option>@endforeach</select></label><template x-if="editing"><input type="hidden" name="type" :value="type"></template>
            <label class="min-w-0 text-xs font-bold">نام رکورد<input name="name" x-model="name" :readonly="editing" :placeholder="meta.name" required maxlength="254" dir="ltr" class="mt-2 w-full rounded-xl border border-slate-300 px-3 py-3 font-mono text-sm read-only:bg-slate-50"><span x-show="fieldErrors?.name" x-text="fieldErrors?.name?.[0]" class="mt-1 block text-xs text-red-700"></span></label>
        </div>
        <p class="mt-2 break-all text-xs leading-6 text-slate-500">برای ریشه دامنه از @ استفاده کنید. نام کامل: <bdi class="font-mono" x-text="fqdn"></bdi></p>
        <p x-show="type === 'NS' && fqdn.replace(/\.$/, '') === zone" role="alert" class="mt-3 rounded-xl bg-amber-50 p-3 text-sm text-amber-900">NS در ریشه دامنه قابل افزودن نیست. نیم‌سرورهای اصلی را در بخش نیم‌سرورهای دامنه ببینید.</p>
        <details class="mt-4 text-slate-600"><summary class="cursor-pointer text-xs font-bold">راهنمای این نوع رکورد</summary><h3 class="text-sm font-bold text-[#0069FF]" x-text="meta.title"></h3><p class="mt-2 text-xs leading-7 text-slate-600" x-text="meta.help"></p><code class="mt-2 block break-all text-left text-xs leading-6" dir="ltr" x-text="meta.example"></code></details>
        <div class="mt-4 space-y-3"><template x-for="(value, index) in values" :key="type + '-' + index"><div class="space-y-2">
            <div x-show="values.length > 1" class="flex items-center justify-between text-xs"><span class="font-bold text-slate-500" x-text="(type === 'NS' ? 'نیم‌سرور ' : 'مقدار ') + (index + 1)"></span><button type="button" x-show="values.length > 1" @click="values.splice(index, 1)" class="text-red-600" :aria-label="'حذف مقدار ' + (index + 1)">حذف مقدار</button></div>
            <div class="flex flex-wrap gap-3"><template x-for="field in meta.fields" :key="type + field.key"><label class="min-w-0 text-xs font-bold" :class="field.number ? 'w-24 grow sm:grow-0' : field.key === 'tag' ? 'w-32 grow sm:grow-0' : 'w-full flex-1 basis-48'"><span x-text="field.label"></span>
                <template x-if="!field.multiline && field.key !== 'tag'"><input x-model="value[field.key]" :type="field.number ? 'number' : 'text'" :min="field.number ? 0 : null" :max="field.number ? (field.max || 65535) : null" :placeholder="type === 'CAA' && field.key === 'value' && value.tag === 'iodef' ? 'mailto:security@example.com' : field.placeholder" required dir="ltr" class="mt-2 w-full rounded-lg border border-slate-300 px-3 py-2.5 font-mono text-sm"></template>
                <template x-if="field.key === 'tag'"><select x-model="value.tag" class="mt-2 w-full rounded-lg border border-slate-300 px-3 py-2.5 font-mono text-sm" dir="ltr"><template x-if="value.tag && !['issue', 'issuewild', 'iodef'].includes(value.tag)"><option :value="value.tag" x-text="value.tag"></option></template><option>issue</option><option>issuewild</option><option>iodef</option></select></template>
                <template x-if="field.multiline"><textarea x-model="value[field.key]" :placeholder="type === 'CAA' && field.key === 'value' && value.tag === 'iodef' ? 'mailto:security@example.com' : field.placeholder" required rows="4" dir="ltr" class="mt-2 w-full resize-y rounded-lg border border-slate-300 px-3 py-2.5 font-mono text-sm"></textarea></template>
            </label></template></div>
        </div></template></div>
        <p x-show="fieldErrors?.content" x-text="fieldErrors?.content?.[0]" class="mt-2 text-xs text-red-700"></p>
        <button type="button" x-show="type !== 'CNAME' && values.length < 100" @click="values.push(blank())" class="mt-3 text-xs font-bold text-[#0069FF]" x-text="type === 'NS' ? '+ افزودن نیم‌سرور دیگر' : '+ افزودن مقدار دیگر برای همین نام'">+ افزودن مقدار دیگر برای همین نام</button>
        <div class="mt-4 flex flex-wrap items-end gap-3">
            <label class="w-44 text-xs font-bold">TTL<select x-model="ttlChoice" @change="if (ttlChoice !== 'custom') ttl = Number(ttlChoice)" class="mt-2 w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm"><option value="300">۵ دقیقه (پیشنهادی)</option><option value="600">۱۰ دقیقه</option><option value="1800">۳۰ دقیقه</option><option value="3600">۱ ساعت</option><option value="86400">۱ روز</option><option value="custom">مقدار دلخواه</option></select></label>
            <label x-show="ttlChoice === 'custom'" class="w-36 text-xs font-bold">TTL (ثانیه)<input x-model="ttl" :disabled="ttlChoice !== 'custom'" type="number" min="60" max="86400" required dir="ltr" class="mt-2 w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm"></label>
            <input type="hidden" name="ttl" :value="ttl">
        </div>
        <p x-show="fieldErrors?.ttl" x-text="fieldErrors?.ttl?.[0]" class="mt-2 text-xs text-red-700"></p>
        <div :class="editorInline ? '' : 'sticky bottom-0 bg-white py-3'" class="mt-5 flex flex-wrap items-center gap-3 border-t border-slate-200 pt-4">
            <button :disabled="busy" class="rounded-lg bg-[#0069FF] px-5 py-2.5 text-sm font-bold text-white disabled:opacity-50" x-text="busy ? 'در حال ذخیره…' : 'ذخیره رکورد'">ذخیره رکورد</button>
            <button type="button" @click="closeEditor()" class="rounded-lg border border-slate-200 bg-white px-4 py-2.5 text-sm">انصراف</button>
            <button x-show="editingRecord" type="button" @click="confirmDelete()" class="mr-auto rounded-lg px-3 py-2.5 text-sm text-red-600 hover:bg-red-50">حذف رکورد</button>
        </div>
    </form>
</dialog>
